FN main
    PROLOGUE
    mov r15, [rip + g_mem_live]
    lea r12, [rip + .Lti_vectors]
    xor r13d, r13d
.Lti_test:
    cmp qword ptr [r12], 0
    je .Lti_ok
    mov rdi, [r12 + 8]
    xor esi, esi
    call snippet_regex_new
    test rax, rax
    jz .Lti_fail
    mov rbx, rax
    mov rdi, rax
    mov rsi, [r12]
    call snippet_transform_indent
    mov r14, rax
    mov r8, [r12 + 32]
    test r8, r8
    setz r8b
    movzx r8d, r8b
    cmp rcx, r8
    jne .Lti_fail
    cmp rdx, [r12 + 24]
    jne .Lti_fail
    test ecx, ecx
    jz 1f
    mov rdi, rax
    mov rsi, [r12 + 16]
    call memeq
    test eax, eax
    jz .Lti_fail
    jmp 2f
1:  test r14, r14
    jnz .Lti_fail
2:  mov rax, [rbx + RX_error]
    cmp rax, [r12 + 32]
    jne .Lti_fail
    mov rax, [rbx + RX_errbyte]
    cmp rax, [r12 + 40]
    jne .Lti_fail
    mov rax, [rbx + RX_work]
    cmp rax, [r12 + 48]
    jne .Lti_fail
    mov rdi, r14
    call mem_free
    mov rdi, rbx
    call snippet_regex_free
    cmp r15, [rip + g_mem_live]
    jne .Lti_fail
    inc r13
    add r12, 56
    jmp .Lti_test
.Lti_ok:
    call snippet_transform_indent_api
    test eax, eax
    jz .Lti_api_fail
    lea rdi, [rip + ok]
    call log_cstr
    xor eax, eax
    EPILOGUE
.Lti_fail:
    lea rdi, [rip + failed]
    call log_cstr
    lea rdi, [rip + out]
    mov rsi, r13
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    mov rsi, [rbx + RX_error]
