    lea rdi, [rip + out]
    mov rsi, [rbx + RX_work]
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 10
    call sb_push_byte
    mov rdi, [rip + out + SB_ptr]
    mov rsi, [rip + out + SB_len]
    call log_write
    mov eax, 1
    EPILOGUE
.Lti_api_fail:
    lea rdi, [rip + api_failed]
    call log_cstr
    mov eax, 1
    EPILOGUE
FN snippet_transform_indent_api
    PROLOGUE SC_SIZE
    mov r15, [rip + g_mem_live]
