    cmp qword ptr [r12 + RX_errbyte], 42
    jne .Lti_api_bad
    cmp qword ptr [r12 + RX_tstage], 77
    jne .Lti_api_bad
    mov rdi, r12
    call snippet_regex_free
    mov edi, 1
    xor esi, esi
